insert into questoes (id,materia,topico,tipo,enunciado,alternativas,aluno) values
  ('bio-t31','biologia','16.1 Modificações na estrutura dos ecossistemas','treino','Como a floresta ajuda a formar chuvas?','["As árvores liberam vapor de água, que ajuda a formar nuvens", "As raízes puxam as nuvens para baixo", "As folhas produzem gelo que vira chuva", "A sombra das árvores esfria o mar"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t32','biologia','16.1 Modificações na estrutura dos ecossistemas','treino','Numa área desmatada, o que acontece com a entrada (infiltração) da água da chuva no solo?','["Aumenta muito, porque não há folhas no caminho", "A água passa a subir do subsolo para a superfície", "Não muda nada", "Diminui: a água escorre pela superfície, e os lençóis subterrâneos e as nascentes recebem menos água"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t33','biologia','16.1 Modificações na estrutura dos ecossistemas','treino','Depois de um desmatamento, o solo tende a ficar:','["Mais fértil para sempre, por causa das cinzas", "Mais úmido e cheio de decompositores", "Mais duro, pobre em nutrientes e exposto ao sol e à chuva", "Coberto de folhas que o protegem"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t34','biologia','16.1 Modificações na estrutura dos ecossistemas','treino','Por que as plantações costumam render menos em terras que sofreram queimadas seguidas?','["Porque parte dos minerais do solo se perde com a fumaça e os microrganismos decompositores morrem", "Porque as queimadas atraem mais chuva", "Porque o fogo aumenta a quantidade de água no solo", "Porque as cinzas deixam o solo rico demais"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t35','biologia','16.1 Modificações na estrutura dos ecossistemas','treino','Quando uma floresta é derrubada, os animais que viviam nela geralmente:','["Migram em busca de abrigo e alimento ou morrem", "Adaptam-se sem problema à cidade", "Ficam mais numerosos", "Passam a viver dentro dos rios"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t36','biologia','16.1 Modificações na estrutura dos ecossistemas','treino','Uma fazenda derrubou toda a mata da margem de um riacho. Anos depois, o riacho sumiu na época da seca. Qual é a explicação mais adequada?','["Sem a mata, entrou menos água no solo e a terra arrastada pela chuva encheu o leito do riacho", "As árvores consumiam a água que agora sobra", "A chuva passou a cair só sobre a floresta vizinha", "O gado bebeu toda a água do riacho"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t37','biologia','16.1 Modificações na estrutura dos ecossistemas','treino','A sombra e a umidade das florestas ajudam a:','["Deixar a região muito mais quente", "Equilibrar a temperatura do ar da região", "Acabar com as chuvas", "Aumentar a erosão do solo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t38','biologia','16.1 Modificações na estrutura dos ecossistemas','treino','Segundo a sequência de efeitos do desmatamento, uma região muito desmatada tende a ter:','["Mais seca, menos chuva e uma vegetação que se recupera mais devagar", "Rios mais fundos e com mais peixes", "Mais chuva e solo mais fértil", "Mais sombra e menos evaporação"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t39','biologia','16.2 Poluição','treino','Sob a luz do Sol, os óxidos de nitrogênio dos escapamentos formam sobre as grandes cidades uma névoa seca chamada:','["Chuva ácida", "Smog fotoquímico", "Neblina marítima", "Camada de ozônio"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t40','biologia','16.2 Poluição','treino','Por que a fuligem (material particulado) é perigosa para a saúde?','["As partículas são tão pequenas que chegam aos alvéolos dos pulmões", "Porque é radioativa", "Porque é feita de metais pesados como o mercúrio", "Porque destrói a camada de ozônio"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t41','biologia','16.2 Poluição','treino','Que tipo de veículo é o maior emissor de material particulado (a fumaça preta)?','["Veículos a diesel", "Bicicletas elétricas", "Carros a álcool", "Veículos movidos a energia solar"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t42','biologia','16.2 Poluição','treino','O dióxido de enxofre (SO₂) do ar das cidades vem principalmente:','["Da queima de derivados do petróleo e do carvão mineral", "Dos vulcões das grandes cidades", "Da respiração das plantas", "Da evaporação da água dos rios"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t43','biologia','16.2 Poluição','treino','Plantas expostas a óxidos de enxofre costumam:','["Produzir mais flores", "Crescer mais rápido", "Ficar com as folhas amareladas e, em concentrações altas, morrer", "Ficar imunes a pragas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t44','biologia','16.2 Poluição','treino','Amebíase e giardíase, transmitidas por água contaminada por esgoto, são causadas por:','["Vermes", "Protozoários", "Vírus", "Bactérias"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t45','biologia','16.2 Poluição','treino','Um aumento da radiação ultravioleta na superfície, causado pela destruição da camada de ozônio, pode provocar:','["Aumento da camada de gelo nos polos", "Mais chuvas e solo mais fértil", "Diminuição da temperatura do planeta", "Câncer de pele, catarata e queda nas colheitas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t46','biologia','16.2 Poluição','treino','Na eutrofização, as algas fazem fotossíntese e liberam oxigênio. Mesmo assim, falta oxigênio na água. Por quê?','["O tapete de algas solta o oxigênio para o ar e bloqueia a luz; as plantas de baixo morrem e sua decomposição consome oxigênio", "Porque o fertilizante transforma o oxigênio em gás carbônico", "Porque os peixes passam a respirar mais", "Porque as algas não fazem fotossíntese na água"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t47','biologia','16.2 Poluição','treino','Detergentes não biodegradáveis, mesmo sem serem muito tóxicos, prejudicam o ambiente porque:','["Esfriam demais a água dos rios", "Matam bactérias que decompõem a matéria orgânica, atrapalhando a decomposição", "Viram adubo para as algas em poucos dias", "Aumentam o oxigênio da água"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t48','biologia','16.2 Poluição','treino','Herbicidas, fungicidas e inseticidas servem para combater, respectivamente:','["Ervas daninhas, fungos e insetos", "Vermes, bactérias e vírus", "Insetos, ervas daninhas e fungos", "Fungos, insetos e ervas daninhas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t49','biologia','16.2 Poluição','treino','Um praguicida "persistente" é aquele que:','["Age só por poucas horas", "Demora muito para se decompor e continua causando efeitos por anos", "Desaparece com a primeira chuva", "Só mata a praga e nenhum outro ser vivo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('bio-t50','biologia','16.2 Poluição','treino','Quando o lixo se decompõe sem oxigênio (decomposição anaeróbia), costuma produzir:','["Apenas água pura", "Adubo pronto em poucas horas", "Oxigênio para o ar", "Gases tóxicos e de mau cheiro, como o gás sulfídrico"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf');
insert into gabarito (questao_id,correta,explicacao) values
  ('bio-t31',0,'As plantas perdem água na forma de vapor (evapotranspiração). Esse vapor sobe e ajuda a formar as nuvens que trazem chuva.'),
  ('bio-t32',3,'Sem a vegetação, a água corre por cima da terra em vez de penetrar. Os lençóis de água e as nascentes vão secando.'),
  ('bio-t33',2,'Sem a cobertura de folhas e detritos, o sol resseca e endurece o solo, e a chuva leva os nutrientes. A terra fica pobre.'),
  ('bio-t34',0,'A queimada leva embora minerais e mata os decompositores, que reciclam os nutrientes. As plantas crescem menos e ficam mais frágeis contra pragas.'),
  ('bio-t35',0,'Sem abrigo e comida, os animais precisam fugir para outras áreas; muitos não conseguem e morrem. É perda de biodiversidade.'),
  ('bio-t36',0,'Sem mata ciliar, a infiltração cai (a nascente seca) e a erosão leva terra para o leito (assoreamento). Na estiagem, o riacho desaparece.'),
  ('bio-t37',1,'As florestas estabilizam o clima: deixam o ar mais fresco e úmido, funcionando como um regulador de temperatura.'),
  ('bio-t38',0,'Menos evapotranspiração leva a menos chuva e mais seca; com o solo pobre e seco, a vegetação demora a se regenerar.'),
  ('bio-t39',1,'"Smog" mistura smoke (fumaça) e fog (neblina). Ele irrita as vias respiratórias e prejudica as plantas.'),
  ('bio-t40',0,'Por serem minúsculas, as partículas entram fundo nas vias respiratórias e podem chegar aos alvéolos, causando doenças.'),
  ('bio-t41',0,'Os motores a diesel são os que mais soltam fuligem. Por isso o controle desse poluente é tão importante nesses veículos.'),
  ('bio-t42',0,'O SO₂ é formado na combustão de combustíveis fósseis. No ar, pode virar SO₃ e participar da chuva ácida.'),
  ('bio-t43',2,'Os vegetais são muito sensíveis aos óxidos de enxofre: as folhas amarelam e, com muita exposição, a planta morre.'),
  ('bio-t44',1,'Bactérias causam cólera e febre tifoide; vírus, hepatite; vermes, esquistossomose. Amebíase e giardíase são causadas por protozoários.'),
  ('bio-t45',3,'Com menos ozônio, mais UV chega ao solo, causando câncer de pele, catarata, queda da imunidade e prejuízo às plantações.'),
  ('bio-t46',0,'O oxigênio das algas da superfície escapa para a atmosfera. Embaixo, sem luz, as plantas morrem, e as bactérias que as decompõem gastam o oxigênio que restava.'),
  ('bio-t47',1,'Sem as bactérias decompositoras, a matéria orgânica não é reciclada, e a decomposição é fundamental para qualquer ambiente.'),
  ('bio-t48',0,'Herbi = erva; fungi = fungo; inseti = inseto. Os nematocidas combatem os nematódeos (vermes).'),
  ('bio-t49',1,'Os praguicidas persistentes são mais estáveis: ficam no ambiente e se acumulam na cadeia alimentar por muito tempo.'),
  ('bio-t50',3,'A decomposição anaeróbia é lenta e libera compostos nocivos, como o gás sulfídrico (cheiro de ovo podre).');
